// fastreplay.cpp — Verilator C++ trace replayer for tsr_core (no cocotb): the fast counterpart of
// tb/common/replay.run_trace + tb/core core_traces for big trace sets. Built and driven by
// tb/fastreplay/run.py (one binary per core configuration and parameter set; fr_config.h holds the
// build's configuration and is generated by run.py).
//
// Per trace directory (sw/sim/include/tsr_trace.h, parsed by tsr_trace_read from sw/sim/tsr_trace.c):
//   1. fresh memory model (memmodel.h): cmd.bin at ch0 CMD_ADDR (clipped at the channel end), then
//      the init regions (init wins); allowed-read bitmap = init beats + command beats; expect bitmap
//   2. PERF snapshot, CMD_ADDR_LO/HI, CMD_COUNT, ARG0..7, CTRL.START through the CSR port
//      (docs/rtl-m2.md §6: master holds valid/addr/we/wdata until the one-cycle csr_ready)
//   3. run until `done` (cycle timeout: replay.estimate_cycles x --timeout-mult)
//   4. at the first cycle of done: no request / write data offered, no read or write in flight
//      (rtl-m2 §4 M7, tsr_core I3); afterwards nothing may be offered until the next START
//   5. STATUS, ERR_CODE, ERR_PC (and ERR_INFO when recorded) == trace
//   6. every expect region bit-exact; written beats == union of the expect regions
//   7. every beat read before being written lies in an init region or the command beats
//   8. PERF deltas: RETIRED == trace perf, PERF_CH_RD_BEATS[c >= 1] == trace perf, every
//      PERF_CH_RD_BEATS[c] == read beats seen at port c, PERF_CH_WAIT[c] <= PERF_CYCLES,
//      PERF_CYCLES ~ cycles START..done, VU / WAITM == 0, MVM == 0 when no MVM executed (> 0
//      when one did, HAS_MVM = 1)
//   9. per-source read beats at the port (id[3:2]): DMA == LD beats, WS == rows_c x ROW_BEATS of
//      every executed MVM (derived from the program like tb/common trace.expected_read_beats; for
//      c >= 1 cross-checked against the trace's perf record), FETCH only on channel 0
//  10. memory protocol (memmodel.h P1..P6) and every RTL assertion ($error / $fatal) of the run
// Traces run back to back on one DUT without reset (START re-initialises the run state), like
// tb/core; --reset-each applies a hardware reset before every trace, and a failing run is always
// followed by one (no cascade). RTL $error / $stop / failed assertions are recorded through a
// vl_stop override (build with -DVL_USER_STOP) instead of aborting the process. Memory regimes rand / fast /
// slow / ordered (tb/core REGIMES; --mem key=value overrides), seeds derived from --seed, the
// trace name and the regime (printed with every result, --run-seed reproduces one run).
// Output: one JSON object per run (--out FILE), a summary line, failures on stderr.
// The DUT-independent part (options, derive, the checks above, the main loop) is in fr_common.h,
// shared with the XRT kernel bench (tb/platform/kernel_dut.h); this file is the tsr_core DUT.

#include <verilated.h>

#include "Vtsr_core.h"
#if VM_TRACE
#include <verilated_vcd_c.h>
#endif

#include "fr_config.h"
#include "fr_common.h"

namespace {

// ---------------------------------------------------------------------------------------------
// The DUT: tsr_core with its CSR port and memory ports (fr_common.h "A DUT class provides")
// ---------------------------------------------------------------------------------------------
class CoreDut {
  public:
    static const char* kind() { return "core"; }
    static bool mem_key(const std::string&) { return false; }

    CoreDut(const Options& opt, int argc, char** argv) {
        ctx_ = std::make_unique<VerilatedContext>();
        ctx_->commandArgs(argc, argv);
        ctx_->fatalOnError(false);
        ctx_->randReset(2);
        ctx_->randSeed((int)((opt.seed * 2654435761u) & 0x7FFFFFFF) | 1);
#if VM_TRACE
        if (!opt.vcd.empty()) ctx_->traceEverOn(true);
#endif
        top_ = std::make_unique<Vtsr_core>(ctx_.get(), "tsr_core");
#if VM_TRACE
        if (!opt.vcd.empty()) {
            vcd_ = std::make_unique<VerilatedVcdC>();
            top_->trace(vcd_.get(), 99);
            vcd_->open(opt.vcd.c_str());
        }
#else
        if (!opt.vcd.empty()) fprintf(stderr, "fastreplay: --vcd needs a build with run.py --waves; ignored\n");
#endif
        fr::MemModel::Config mc;
        mc.num_ch = NUM_CH;
        mc.ch_bytes = FR_CH_BYTES;
        const uint64_t lim_a = FR_CH_BYTES / 64, lim_b = 1ull << AW;
        mc.limit = std::min(lim_a, lim_b);
        mc.rd_outstanding = FR_RD_OUTSTANDING;
        mc.has_mvm = FR_HAS_MVM != 0;
        mem_.configure(mc);
        // inputs idle
        top_->clk = 0;
        top_->rst_n = 0;
        top_->csr_valid = 0;
        top_->csr_we = 0;
        top_->csr_addr = 0;
        top_->csr_wdata = 0;
        drive();
    }
    ~CoreDut() {
#if VM_TRACE
        if (vcd_) vcd_->close();
#endif
        if (top_) top_->final();
    }

    uint64_t cycles() const { return cyc_; }
    fr::MemModel& mem() { return mem_; }
    bool running() const { return running_; }
    bool finished() const { return finished_; }
    uint64_t start_cyc() const { return start_cyc_; }
    uint64_t done_cyc() const { return done_cyc_; }
    std::vector<std::string>& done_errs() { return done_errs_; }

    // Hardware reset: rst_n low for 5 cycles; the memory drops everything in flight.
    void hw_reset() {
        top_->rst_n = 0;
        in_reset_ = true;
        running_ = false;
        csr_active_ = false;
        top_->csr_valid = 0;
        top_->csr_we = 0;
        mem_.set_active(false);
        for (int i = 0; i < 6; ++i) step();
        top_->rst_n = 1;
        in_reset_ = false;
        step();
    }

    std::string check_constants() { return check_core_constants(*this); }

    void prepare(const fr::Regime& reg, uint64_t seed) { mem_.prepare(reg, seed); }

    // CMD_ADDR_LO/HI, CMD_COUNT, ARG0..7, CTRL.START through the CSR port.
    void start(const tsr_trace& tr, bool* ok) {
        csr(TSR_CSR_CMD_ADDR_LO, true, (uint32_t)tr.cmd_addr_beat, ok);
        csr(TSR_CSR_CMD_ADDR_HI, true, (uint32_t)(tr.cmd_addr_beat >> 32), ok);
        csr(TSR_CSR_CMD_COUNT, true, tr.cmd_count, ok);
        for (unsigned i = 0; i < 8; ++i) csr(TSR_CSR_ARG0 + 4 * i, true, tr.args[i], ok);
        finished_ = false;
        csr(TSR_CSR_CTRL, true, TSR_CTRL_START, ok);
    }

    // BUSY cycles: observed START handshake .. first done sample + 2 with tsr_csr (rtl-m2 P5)
    void perf_window(uint64_t cycles, uint64_t* lo, uint64_t* hi) const {
        *lo = cycles;
        *hi = cycles + 4;
    }

    void post_run(const tsr_trace&, RunResult&, bool) {}

    // One clock cycle: inputs settle (clk low), sample, model edge, DUT edge, drive.
    void step() {
        top_->clk = 0;
        top_->eval();
#if VM_TRACE
        if (vcd_) vcd_->dump(ctx_->time());
#endif
        ctx_->timeInc(5);
        sample();
        if (csr_active_ && top_->csr_ready) {
            csr_rdata_ = top_->csr_rdata;
            csr_hs_ = true;
        }
        if (running_) {
            if (!top_->done) seen_low_ = true;
            else if (seen_low_) on_done();
        }
        if (in_reset_) mem_.reset_transactions();
        else mem_.edge(out_);
        top_->clk = 1;
        top_->eval();
#if VM_TRACE
        if (vcd_) vcd_->dump(ctx_->time());
#endif
        ctx_->timeInc(5);
        ++cyc_;
        if (csr_hs_ && csr_active_) {
            csr_active_ = false;
            top_->csr_valid = 0;
            top_->csr_we = 0;
            if (csr_we_ && csr_addr_ == TSR_CSR_CTRL && (csr_wdata_ & TSR_CTRL_START) && !running_) {
                running_ = true;
                seen_low_ = false;
                finished_ = false;
                start_cyc_ = cyc_;
                mem_.set_active(true);
            }
        }
        drive();
    }

    // One CSR transfer (rtl-m2 §6), then one idle cycle. *ok = false on a timeout.
    uint32_t csr(uint32_t addr, bool we, uint32_t wdata, bool* ok) {
        top_->csr_valid = 1;
        top_->csr_we = we;
        top_->csr_addr = addr;
        top_->csr_wdata = wdata;
        csr_active_ = true;
        csr_hs_ = false;
        csr_addr_ = addr;
        csr_we_ = we;
        csr_wdata_ = wdata;
        for (uint32_t n = 0; csr_active_; ++n) {
            if (n >= CSR_TIMEOUT) {
                csr_active_ = false;
                top_->csr_valid = 0;
                top_->csr_we = 0;
                *ok = false;
                return 0;
            }
            step();
        }
        csr_hs_ = false;
        step();
        return csr_rdata_;
    }

  private:
    std::unique_ptr<VerilatedContext> ctx_;
    std::unique_ptr<Vtsr_core> top_;
#if VM_TRACE
    std::unique_ptr<VerilatedVcdC> vcd_;
#endif
    fr::MemModel mem_;
    ChOut out_[NUM_CH];
    uint64_t cyc_ = 0;
    bool in_reset_ = true;
    // CSR transfer in progress
    bool csr_active_ = false, csr_hs_ = false;
    uint32_t csr_addr_ = 0, csr_wdata_ = 0, csr_rdata_ = 0;
    bool csr_we_ = false;
    // run state
    bool running_ = false, seen_low_ = false, finished_ = false;
    uint64_t start_cyc_ = 0, done_cyc_ = 0;
    std::vector<std::string> done_errs_;

    void sample() {
        for (unsigned c = 0; c < NUM_CH; ++c) {
            ChOut& o = out_[c];
            o.rd_req_valid = getb(top_->m_rd_req_valid, c, 1);
            if (o.rd_req_valid) {
                o.rd_req_addr = getb(top_->m_rd_req_addr, c * AW, AW);
                o.rd_req_len = (unsigned)getb(top_->m_rd_req_len, c * LEN_W, LEN_W);
                o.rd_req_id = (unsigned)getb(top_->m_rd_req_id, c * ID_W, ID_W);
            }
            o.rd_rsp_ready = getb(top_->m_rd_rsp_ready, c, 1);
            o.wr_req_valid = getb(top_->m_wr_req_valid, c, 1);
            if (o.wr_req_valid) {
                o.wr_req_addr = getb(top_->m_wr_req_addr, c * AW, AW);
                o.wr_req_len = (unsigned)getb(top_->m_wr_req_len, c * LEN_W, LEN_W);
                o.wr_req_id = (unsigned)getb(top_->m_wr_req_id, c * ID_W, ID_W);
            }
            o.wr_dat_valid = getb(top_->m_wr_dat_valid, c, 1);
            if (o.wr_dat_valid) {
                o.wr_dat_data = reinterpret_cast<const uint8_t*>(wide_words_c(top_->m_wr_dat_data) + 16 * c);
                o.wr_dat_last = getb(top_->m_wr_dat_last, c, 1);
            }
            o.wr_rsp_ready = getb(top_->m_wr_rsp_ready, c, 1);
        }
    }

    void drive() {
        uint64_t rqr = 0, rsv = 0, rsl = 0, wqr = 0, wdr = 0, wsv = 0;
        for (unsigned c = 0; c < NUM_CH; ++c) {
            const ChIn& in = mem_.in_[c];
            rqr |= (uint64_t)in.rd_req_ready << c;
            rsv |= (uint64_t)in.rd_rsp_valid << c;
            rsl |= (uint64_t)in.rd_rsp_last << c;
            wqr |= (uint64_t)in.wr_req_ready << c;
            wdr |= (uint64_t)in.wr_dat_ready << c;
            wsv |= (uint64_t)in.wr_rsp_valid << c;
            if (in.rd_rsp_new) memcpy(wide_words(top_->m_rd_rsp_data) + 16 * c, in.rd_rsp_data, 64);
            if (in.rd_rsp_valid) setb(top_->m_rd_rsp_id, c * ID_W, ID_W, in.rd_rsp_id);
            if (in.wr_rsp_valid) setb(top_->m_wr_rsp_id, c * ID_W, ID_W, in.wr_rsp_id);
        }
        setb(top_->m_rd_req_ready, 0, NUM_CH, rqr);
        setb(top_->m_rd_rsp_valid, 0, NUM_CH, rsv);
        setb(top_->m_rd_rsp_last, 0, NUM_CH, rsl);
        setb(top_->m_wr_req_ready, 0, NUM_CH, wqr);
        setb(top_->m_wr_dat_ready, 0, NUM_CH, wdr);
        setb(top_->m_wr_rsp_valid, 0, NUM_CH, wsv);
    }

    void on_done() {
        running_ = false;
        finished_ = true;
        done_cyc_ = cyc_;
        // DONE => quiescent (rtl-m2 §4 M7): nothing offered in this cycle, nothing in flight.
        for (unsigned c = 0; c < NUM_CH; ++c) {
            if (out_[c].rd_req_valid || out_[c].wr_req_valid || out_[c].wr_dat_valid)
                done_errs_.push_back(strf("ch%u: request / write data offered in the first cycle of done", c));
        }
        if (!mem_.idle()) done_errs_.push_back("memory traffic in flight at done: " + mem_.busy_desc());
        mem_.set_active(false);
    }
};

}  // namespace

int main(int argc, char** argv) { return replay_main<CoreDut>(argc, argv); }
